package com.witchersbestiary.contracts.hunt;
import java.util.*;import java.util.concurrent.CompletableFuture;import java.util.function.*;
import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.*;import net.minecraft.world.chunk.ChunkStatus;
import net.fabricmc.fabric.api.event.lifecycle.v1.*;
/** A finite, shared asynchronous survey. Never joins a future or retains permanent chunk tickets. */
public final class HuntTerrain {
 private static final net.minecraft.server.world.ChunkTicketType<UUID> SURVEY=net.minecraft.server.world.ChunkTicketType.create("witchersbestiary:contract_survey",Comparator.<UUID>naturalOrder(),200);
 private static final LinkedHashMap<UUID,Job> JOBS=new LinkedHashMap<>();
 private static final class Job {ServerPlayerEntity player;BlockPos origin;BooleanSupplier valid,attempt;Consumer<Boolean> done;List<ChunkPos> chunks=List.of();CompletableFuture<?> future;int patch,index,age;}
 public static boolean pending(UUID id){return JOBS.containsKey(id);}
 public static void request(ServerPlayerEntity p,BlockPos origin,BooleanSupplier valid,BooleanSupplier attempt,Consumer<Boolean> done){if(pending(p.getUuid()))return;if(JOBS.size()>=8)throw new IllegalStateException("Terrain preparation is busy; retry");var j=new Job();j.player=p;j.origin=origin.toImmutable();j.valid=valid;j.attempt=attempt;j.done=done;JOBS.put(p.getUuid(),j);}
 private static List<ChunkPos> patch(Job j){int n=j.patch;double angle=n*2.399963229728653;int radius=80+Math.floorMod((n%64)*73,251);int x=j.origin.getX()+(int)(Math.cos(angle)*radius),z=j.origin.getZ()+(int)(Math.sin(angle)*radius);var unique=new LinkedHashSet<ChunkPos>();for(int d=0;d<=84;d+=12){int cx=(x-(int)(Math.cos(angle)*d))>>4,cz=(z-(int)(Math.sin(angle)*d))>>4;for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){var cp=new ChunkPos(cx+dx,cz+dz);if(j.player.getServerWorld().getWorldBorder().contains(cp.getCenterAtY(j.origin.getY())))unique.add(cp);}}return List.copyOf(unique);}
 private static void release(Job j){for(var cp:j.chunks)j.player.getServerWorld().getChunkManager().removeTicket(SURVEY,cp,0,j.player.getUuid());}
 public static void initialize(){ServerTickEvents.END_SERVER_TICK.register(s->{if(JOBS.isEmpty())return;var entry=JOBS.entrySet().iterator().next();var j=entry.getValue();JOBS.remove(entry.getKey());if(j.player.isRemoved()||!j.valid.getAsBoolean()){release(j);return;}for(int n=0;n<j.index+(j.future!=null?1:0);n++){var cp=j.chunks.get(n);j.player.getServerWorld().getChunkManager().addTicket(SURVEY,cp,0,j.player.getUuid());}boolean finished=false;try{if(++j.age>1800){j.done.accept(false);finished=true;}else if(j.future!=null){if(j.future.isDone()){j.future.getNow(null);j.future=null;j.index++;}}else if(j.index<j.chunks.size()){var cp=j.chunks.get(j.index);j.player.getServerWorld().getChunkManager().addTicket(SURVEY,cp,0,j.player.getUuid());j.future=j.player.getServerWorld().getChunkManager().getChunkFutureSyncOnMainThread(cp.x,cp.z,ChunkStatus.FULL,true);}else if(j.attempt.getAsBoolean()){j.done.accept(true);finished=true;}else if(j.patch>=16){j.done.accept(false);finished=true;}else{release(j);j.chunks=patch(j);j.patch++;j.index=0;}}catch(RuntimeException error){j.done.accept(false);finished=true;}if(!finished)JOBS.put(entry.getKey(),j);else release(j);});ServerLifecycleEvents.SERVER_STOPPED.register(s->JOBS.clear());}
}
